DELIMITER $$
CREATE TRIGGER req_qty_guard BEFORE INSERT ON issue_request FOR EACH ROW
BEGIN
IF NEW.qty>(SELECT amount FROM Stock WHERE mat_num=NEW.mat_num) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='申请量超过库存'; END IF;
END$$
DELIMITER ;

DELIMITER $$
CREATE TRIGGER req_deduct AFTER INSERT ON issue_request FOR EACH ROW
BEGIN
UPDATE Stock SET amount=amount-NEW.qty WHERE mat_num=NEW.mat_num;
END$$
DELIMITER ;

DELIMITER $$
CREATE TRIGGER log_unit_change AFTER UPDATE ON Stock FOR EACH ROW
BEGIN
IF NOT (OLD.unit<=>NEW.unit) THEN INSERT INTO unit_audit VALUES(NEW.mat_num,OLD.unit,NEW.unit); END IF;
END$$
DELIMITER ;

DELIMITER $$
CREATE TRIGGER clean_dispatch_lines AFTER DELETE ON dispatch_ticket FOR EACH ROW
BEGIN
DELETE FROM dispatch_line WHERE ticket_id=OLD.ticket_id;
END$$
DELIMITER ;
